import pathlib,json,statistics,collections,hashlib
p=pathlib.Path('/home/vrondelli/projects/cyberAlchemy-v2/implementation/agent-reasoning-engine/benchmarks/glm-episodes-v1/evidence/repeatability-2026-09-07')
r=json.loads((p/'result.json').read_text());m=json.loads((p/'manifest.json').read_text())
for s in m['sources']:assert hashlib.sha256(pathlib.Path(s['path']).read_bytes()).hexdigest()==s['sha256']
trials=[]
for trial in r['trials']:
 report=trial['report'];a=report['arms'][0];complete=json.loads((p/f"trial-{trial['index']:02d}/arm-0/completed.json").read_text())
 passed=a.get('verified_repair') is True;continuity=a.get('continuity',{}).get('passed') is True
 reasons=a.get('reasons',[])
 oracle=complete.get('verification',{});oracle=oracle if isinstance(oracle,dict) else {}
 if not passed and not reasons:reasons=oracle.get('reason_codes',[]) or ['no-verified-repair']
 headroom=[d['soft_headroom_tokens'] for d in complete.get('dispatch_headroom',[])]
 assert all(v>0 for v in headroom)
 trials.append({'index':trial['index'],'repetition':trial['repetition'],'episode':trial['episode'],'policy':trial['policy'],'repair':passed,'continuity':continuity,'joint_pass':passed and continuity,'reasons':reasons,'model_attempts':report['totals']['model_attempts'],'tokenizer_attempts':report['totals']['tokenizer_attempts'],'input_tokens':report['totals']['input_tokens'],'output_tokens':report['totals']['output_tokens'],'elapsed_ms':a['elapsed_ms'],'minimum_soft_headroom':min(headroom) if headroom else None,'recycles':complete['recycles'],'repeated_successful_file_reads':a['read_activity']['repeated_successful_file_reads']})
def stats(items):
 known=lambda k:[x[k] for x in items if isinstance(x[k],(int,float))]
 return {'trials':len(items),'repairs':sum(t['repair'] for t in items),'continuity_passes':sum(t['continuity'] for t in items),'joint_passes':sum(t['joint_pass'] for t in items),'model_attempts':sum(known('model_attempts')),'tokenizer_attempts':sum(known('tokenizer_attempts')),'known_input_tokens':sum(known('input_tokens')),'input_usage_unknown_trials':len(items)-len(known('input_tokens')),'known_output_tokens':sum(known('output_tokens')),'output_usage_unknown_trials':len(items)-len(known('output_tokens')),'median_elapsed_ms':statistics.median(known('elapsed_ms')),'min_elapsed_ms':min(known('elapsed_ms')),'max_elapsed_ms':max(known('elapsed_ms')),'mean_model_attempts':statistics.mean(known('model_attempts'))}
groups=[]
for episode in ['retention-tool-pairs','exact-json-scoring']:
 for policy in ['clear-v1','recent-observations-v2']:
  items=[t for t in trials if t['episode']==episode and t['policy']==policy]
  if items:groups.append({'episode':episode,'policy':policy,**stats(items)})
policies=[{'policy':policy,**stats([t for t in trials if t['policy']==policy])} for policy in ['clear-v1','recent-observations-v2'] if any(t['policy']==policy for t in trials)]
summary={'authority_effect':'none','status':r['status'],'planned':12,'completed':len(trials),'sources_unchanged':True,'totals':stats(trials),'groups':groups,'policies':policies,'trials':trials,'failure_counts':dict(collections.Counter(reason for t in trials for reason in t['reasons'])),'open_questions_ref':'README.md#open-questions'}
(p/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# Frozen repeatability benchmark — 2026-09-07','',f"Completed {len(trials)} of 12 predeclared trials. Joint repair-and-continuity passes: {sum(t['joint_pass'] for t in trials)}/{len(trials)}. No tuning or failure replacement occurred.",'','| Task | Policy | Repair | Continuity | Both | Mean model calls | Median arm time |','| --- | --- | ---: | ---: | ---: | ---: | ---: |']
for g in groups:lines.append(f"| {g['episode']} | {g['policy']} | {g['repairs']}/{g['trials']} | {g['continuity_passes']}/{g['trials']} | {g['joint_passes']}/{g['trials']} | {g['mean_model_attempts']:.1f} | {g['median_elapsed_ms']/1000:.1f}s |")
lines+=['','A repair pass means all eight independent oracle checks passed. Continuity is','assessed separately and requires all prescribed reads/delivery and meaningful','archive recovery after recycling. Three repetitions per group are too few to','establish reliable superiority; no default policy was changed.','','## All trial outcomes','','| Trial | Rep | Task | Policy | Repair | Continuity | Model/tokenizer calls | Outcome |','| --- | ---: | --- | --- | --- | --- | --- | --- |']
for t in trials:lines.append(f"| [trial-{t['index']:02d}](trial-{t['index']:02d}/checked-report.json) | {t['repetition']} | {t['episode']} | {t['policy']} | {'Pass' if t['repair'] else 'Fail'} | {'Pass' if t['continuity'] else 'Fail'} | {t['model_attempts']}/{t['tokenizer_attempts']} | {', '.join(t['reasons']) or ('Joint pass' if t['joint_pass'] else 'Missing continuity')} |")
t=summary['totals']
lines+=['','## Cost and latency','',f"Recorded attempts: {t['model_attempts']} model and {t['tokenizer_attempts']} tokenizer calls. Known input/output tokens: {t['known_input_tokens']}/{t['known_output_tokens']}. Trials with unknown input/output usage: {t['input_usage_unknown_trials']}/{t['output_usage_unknown_trials']}.",f"Arm wall times range from {t['min_elapsed_ms']/1000:.1f}s to {t['max_elapsed_ms']/1000:.1f}s (median {t['median_elapsed_ms']/1000:.1f}s). Timing includes model/tokenizer latency and local execution; no monetary price estimate is inferred.",'','Per-task/policy token usage, latency and every arm’s counters are in','[summary.json](summary.json). All failures are counted; none were replaced.','','## Frozen setup and evidence','','The [plan](PLAN.md) and [manifest](manifest.json) were written before live calls.','The same final candidate, task bytes, fixtures and policies were used throughout.','Source hashes matched before and after each arm and at final aggregation. The','previous 340-test local suite was not rerun because its sources were unchanged;','its [log](prior-tests.tap) is included. There were no code or prompt changes.','','Each independent arm used explicit-finalization-v3, bounded-reads-v1 and','inspected-mutation-v1 with its assigned retention policy. Order alternated across','repetitions as recorded in the manifest. Each arm retained 12 model/24 tokenizer','attempts and 580 seconds of execution; total attempt caps were144/288. Calls','were not automatically retried. Individual arm failures did not replace or cancel','other predeclared arms. Every report passed recorded integrity/policy/accounting','checks and tasks remained identical across repetitions.','','All actual dispatches remained below the 8000 soft token limit, including the','2048 output reserve and256 margin; hard limit16384. Headroom and recycle counts','are in summary.json. This measures ARE admission and observable recycling, not','provider-internal compaction. Patches were verified in isolated copies only;','original fixtures remained unchanged. No product patch was applied.','','Checked reports validate recorded receipts, not cryptographic authenticity or a','fresh oracle replay. Exports include visible traces/candidates but exclude raw','message history and provider reasoning. Complete private report inputs remain','under /tmp/are-glm-repeatability-2026-09-07; these exports are not complete','reportRun inputs. Authority effect none; defaults, publication and deployment','remain unchanged.','','## Open Questions','','- Will these results hold with more independent repetitions and broader tasks?','- What changes across context-window sizes on this same frozen candidate?','- Which failures come from model behavior versus provider/credential availability?','- What evidence would justify changing the default policy?','']
(p/'README.md').write_text('\n'.join(lines))
print(json.dumps({'totals':summary['totals'],'groups':groups,'failure_counts':summary['failure_counts']},indent=2))
